/**
 * Looping call ring sounds.
 *
 * - 'ringback': what the caller hears while the other side is ringing.
 * - 'ringtone': what the person being called hears.
 *
 * One ring at a time, process-wide: starting a ring stops any other, and
 * every start returns a stop function so effects can clean up exactly the
 * ring they started. The audio files are generated by
 * scripts/generate-voice-cues.cjs; replacing them with custom sounds needs no
 * code change as long as the file names stay the same.
 */

export type CallRingKind = 'ringback' | 'ringtone';

const FILES: Record<CallRingKind, string> = {
  ringback: 'ncore-ringback.wav',
  ringtone: 'ncore-ringtone.wav',
};

const VOLUME: Record<CallRingKind, number> = {
  ringback: 0.45,
  ringtone: 0.7,
};

let current: { kind: CallRingKind; audio: HTMLAudioElement; token: number } | null = null;
let nextToken = 1;

export function startCallRing(kind: CallRingKind): () => void {
  if (typeof Audio === 'undefined') return () => undefined;
  if (current?.kind === kind) {
    // Already ringing this kind; hand back a stop for the existing ring.
    const token = current.token;
    return () => stopIfCurrent(token);
  }
  stopCallRing();

  const audio = new Audio(`${import.meta.env.BASE_URL}sounds/${FILES[kind]}`);
  audio.loop = true;
  audio.volume = VOLUME[kind];
  const token = nextToken++;
  current = { kind, audio, token };
  // Autoplay can be refused before any user interaction; a silent ring is
  // better than a thrown error in the call flow.
  void audio.play().catch(() => undefined);
  return () => stopIfCurrent(token);
}

function stopIfCurrent(token: number) {
  if (current?.token === token) stopCallRing();
}

export function stopCallRing(): void {
  if (!current) return;
  try {
    current.audio.pause();
    current.audio.currentTime = 0;
  } catch {
    // ignore
  }
  current = null;
}
